mapper.select:
select * from (
    SELECT mp.*,mi.MACHINE_NAME
    FROM T_TC_MOUTH_PLATE mp
    LEFT JOIN T_TC_MACHINE_INFO mi
    ON mp.MACHINE_ID = mi.ID
    where mp.del_flag = '0'

        and INSTR(mouth_plate_code, #{mouthPlateCode}) > 0

    and mp.machine_id = #{machineId}
    and mp.status = #{status}

        order by mp.CREATE_TIME desc

) t

    order by ${orderStr}

SELECT count(1)
FROM T_TC_MOUTH_PLATE mp
LEFT JOIN T_TC_MACHINE_INFO mi
ON mp.MACHINE_ID = mi.ID
where mp.del_flag = '0'
and mp.mouth_plate_code = #{mouthPlateCode}
and mp.machine_id = #{machineId}
and mp.id != #{id}

mapper.update:
merge into T_TC_MOUTH_PLATE a USING (
select #{MouthPlate.mouthPlateCode,jdbcType=VARCHAR} mouth_plate_code, #{MouthPlate.machineId,jdbcType=DOUBLE} machine_id, #{MouthPlate.status,jdbcType=VARCHAR} status, #{MouthPlate.createBy,jdbcType=VARCHAR} create_by, #{MouthPlate.createTime,jdbcType=DATE} create_time, #{MouthPlate.updateBy,jdbcType=VARCHAR} update_by, #{MouthPlate.updateTime,jdbcType=DATE} update_time, #{MouthPlate.remark,jdbcType=VARCHAR} remark from dual
) b ON (a.mouth_plate_code = b.mouth_plate_code and a.machine_id = b.machine_id and a.del_flag = '0') WHEN MATCHED THEN UPDATE SET a.status = b.status, a.update_by = b.create_by, a.update_time = sysdate, a.remark = b.remark WHEN NOT MATCHED THEN INSERT (a.id, a.mouth_plate_code, a.machine_id, a.status, a.create_by, a.create_time, a.remark,a.del_flag) values (SEQ_PUBLIC.NEXTVAL, b.mouth_plate_code, b.machine_id, b.status, b.create_by, sysdate, b.remark,'0')
